# outputs/ct06_clock_tree.txt

# 1. Identify the clock net and the root buffer.
# The clock port is 'clk'. The net driving it is likely 'clk'.
set clk_net [get_net clk]
if {$clk_net == "NULL"} {
    # Fallback: try to find the clock net by name if port and net names differ
    set clk_net [lindex [get_nets -filter "name =~ *clk*" -quiet] 0]
}

if {$clk_net == "NULL"} {
    puts "Error: Could not find clock net."
    exit 1
}

# Find the root buffer: the buffer instance driven by the clock port/net 'clk'
# We look for instances that are buffers (BUF_*) driven by the clk net.
# The output pin of the buffer is usually 'Y' or 'A' depending on cell, but typically 'Y' for buffers.
# Let's find all pins driven by clk_net.
set clk_pins [get_pins -of_objects $clk_net]

set root_bufs [list]
foreach pin $clk_pins {
    set inst [get_property INSTANCE $pin]
    set cell_name [get_property LIB_CELL_NAME [get_cells $inst]]
    # Check if it's a buffer cell
    if {[string match "BUF_*" $cell_name] || [string match "CLKBUF_*" $cell_name]} {
        lappend root_bufs $inst
    }
}

# There should be one root buffer. If multiple, take the first one (or handle error).
if {[llength $root_bufs] == 0} {
    puts "Error: No root buffer found driven by clk."
    exit 1
}
set root_inst [lindex $root_bufs 0]

# 2. Traverse the clock tree to assign levels and count sinks.
# We will use a queue for BFS.
# Data structure: list of lists {instance_name level}
set queue [list [list $root_inst 1]]
set visited [dict create]
set result_lines [list]

# Helper function to get output nets of a buffer instance
# Buffers typically have output pin 'Y'.
set buf_output_pins [list Y A]

# Helper function to count register sinks on a net
proc count_reg_sinks {net_name} {
    set sink_count 0
    # Get all pins connected to this net
    set pins [get_pins -of_objects [get_nets $net_name]]

    foreach pin $pins {
        # Check if the pin is a clock input pin of a flip-flop
        set cell [get_property CELL $pin]
        set is_ff 0
        # Common FF cell names in Nangate45 start with DFF, DFFR, DFFS, etc.
        if {[string match "DFF*" $cell] || [string match "FD*" $cell] || [string match "SR*" $cell]} {
            set is_ff 1
        }

        # Check if the pin is a clock pin
        set pin_name [get_property NAME $pin]
        set is_clk_pin 0
        # Standard clock pin names are usually 'CK', 'C', 'CLK'
        if {$pin_name == "CK" || $pin_name == "C" || $pin_name == "CLK"} {
            set is_clk_pin 1
        }

        if {$is_ff && $is_clk_pin} {
            incr sink_count
        }
    }
    return $sink_count
}

while {[llength $queue] > 0} {
    # Dequeue
    set current [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set inst [lindex $current 0]
    set level [lindex $current 1]

    # Skip if already visited (should not happen in a tree, but safety)
    if {[dict exists $visited $inst]} {
        continue
    }
    dict set visited $inst 1

    # Get the instance name and cell name
    set inst_name [get_name $inst]
    set cell_name [get_property LIB_CELL_NAME [get_cells $inst]]

    # Get the output net(s) of this buffer
    # Buffers usually have one output.
    set output_nets [list]
    foreach op $buf_output_pins {
        set pin [get_pins -of_objects [get_cells $inst] -filter "NAME == $op"]
        if {$pin != ""} {
            set net [get_net -of_objects $pin]
            if {$net != "NULL"} {
                lappend output_nets $net
            }
        }
    }

    # If no output net found, it's a leaf. Count sinks (should be 0 if it doesn't drive anything, or FFs).
    # Actually, we need to process each output net. In a simple buffer tree, there's one output.

    set current_sink_count 0

    foreach out_net $output_nets {
        # Count register sinks driven by this net
        set sinks [count_reg_sinks $out_net]
        incr current_sink_count $sinks

        # Find child buffers driven by this net
        # Get pins driven by this net
        set driven_pins [get_pins -of_objects $out_net]

        foreach driven_pin $driven_pins {
            set child_inst [get_property INSTANCE $driven_pin]
            set child_cell [get_property LIB_CELL_NAME [get_cells $child_inst]]

            # Check if child is a buffer
            if {[string match "BUF_*" $child_cell] || [string match "CLKBUF_*" $child_cell]} {
                # Check if not already visited
                if {![dict exists $visited $child_inst]} {
                    lappend queue [list $child_inst [expr {$level + 1}]]
                }
            }
        }
    }

    # Append to result
    lappend result_lines "$inst_name $cell_name $level $current_sink_count"
}

# Write to output file
set output_file "outputs/ct06_clock_tree.txt"
file delete -force $output_file
file mkdir [file dirname $output_file]
set fid [open $output_file w]
foreach line $result_lines {
    puts $fid $line
}
close $fid

puts "Clock tree description written to $output_file"

# outputs/ct06_clock_tree.txt

# 1. Identify the clock net
set clk_net [get_net clk]
if {$clk_net == "NULL"} {
    puts "Error: Clock net 'clk' not found."
    exit 1
}

# 2. Find root buffers
# Root buffers are instances driven directly by the clock net.
# Get output pins of the clock net
set clk_out_pins [get_pins -of_objects $clk_net -filter direction == output]

set root_bufs [list]
foreach pin $clk_out_pins {
    # Get the instance driving this pin
    # In OpenSTA, get_property INSTANCE on a pin returns the instance name if it's an instance pin?
    # Actually, get_pins returns pin objects. 
    # To get the instance, we can use get_cells -of_objects $pin
    set insts [get_cells -of_objects $pin]
    if {[llength $insts] > 0} {
        set inst [lindex $insts 0]
        set cell_name [get_property LIB_CELL_NAME $inst]
        # Check if it is a buffer
        if {[string match "BUF_*" $cell_name] || [string match "CLKBUF_*" $cell_name]} {
            lappend root_bufs $inst
        }
    }
}

if {[llength $root_bufs] == 0} {
    puts "Warning: No root buffers found. Trying alternative method."
    # Alternative: Find all BUF/CLKBUF instances and check if their input is clk_net
    set all_bufs [get_cells -filter "lib_cell_name =~ BUF_* || lib_cell_name =~ CLKBUF_*"]
    foreach inst $all_bufs {
        set input_pins [get_pins -of_objects $inst -filter direction == input]
        foreach ipin $input_pins {
            set ipin_net [get_net -of_objects $ipin]
            if {$ipin_net == $clk_net} {
                lappend root_bufs $inst
                break
            }
        }
    }
}

if {[llength $root_bufs] == 0} {
    puts "Error: No clock tree buffers found."
    exit 1
}

# Use the first root buffer as the start of BFS. 
# If there are multiple roots (e.g. for different clocks), we should handle them.
# The task implies a single clock tree for 'clk'.
set root_inst [lindex $root_bufs 0]

# 3. BFS to determine levels and count sinks
set queue [list [list $root_inst 1]]
set visited [dict create]
set result_lines [list]

# Helper to count register sinks on a net
proc count_reg_sinks {net} {
    set count 0
    # Get all pins connected to the net
    set pins [get_pins -of_objects $net]
    foreach pin $pins {
        # Check if it's a clock input pin
        set pin_name [get_property NAME $pin]
        if {$pin_name != "CK" && $pin_name != "C" && $pin_name != "CLK"} {
            continue
        }

        # Check if the cell is a flip-flop
        set inst [get_property INSTANCE $pin]
        set cell_name [get_property LIB_CELL_NAME $inst]
        if {[string match "DFF*" $cell_name] || [string match "FD*" $cell_name] || [string match "SR*" $cell_name] || [string match "JKFF*" $cell_name] || [string match "TFF*" $cell_name]} {
            incr count
        }
    }
    return $count
}

while {[llength $queue] > 0} {
    set current [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set inst [lindex $current 0]
    set level [lindex $current 1]

    if {[dict exists $visited $inst]} {
        continue
    }
    dict set visited $inst 1

    set inst_name [get_name $inst]
    set cell_name [get_property LIB_CELL_NAME $inst]

    # Get output nets of this buffer
    set output_nets [list]
    set out_pins [get_pins -of_objects $inst -filter direction == output]
    foreach opin $out_pins {
        set net [get_net -of_objects $opin]
        if {$net != "NULL"} {
            lappend output_nets $net
        }
    }

    set sink_count 0
    foreach net $output_nets {
        # Count register sinks
        incr sink_count [count_reg_sinks $net]

        # Find child buffers driven by this net
        set driven_pins [get_pins -of_objects $net]
        foreach driven_pin $driven_pins {
            set child_insts [get_cells -of_objects $driven_pin]
            foreach child_inst $child_insts {
                set child_cell_name [get_property LIB_CELL_NAME $child_inst]
                if {[string match "BUF_*" $child_cell_name] || [string match "CLKBUF_*" $child_cell_name]} {
                    if {![dict exists $visited $child_inst]} {
                        lappend queue [list $child_inst [expr {$level + 1}]]
                    }
                }
            }
        }
    }

    lappend result_lines "$inst_name $cell_name $level $sink_count"
}

# Write output
set output_file "outputs/ct06_clock_tree.txt"
file delete -force $output_file
file mkdir [file dirname $output_file]
set fid [open $output_file w]
foreach line $result_lines {
    puts $fid $line
}
close $fid

puts "Clock tree description written to $output_file"

# Create output directory if it doesn't exist
file mkdir outputs

# Open the output file
set outfile [open outputs/io_ports.txt w]

# Get all top-level ports
set ports [get_ports -filter "is_top_level==1"]

foreach port $ports {
    # Get direction
    set dir [get_property DIRECTION $port]

    # Get port name
    set name [get_property NAME $port]

    # Get width
    set width [get_property WIDTH $port]

    # Handle cases where width might be empty or 1
    if {$width eq ""} {
        set width 1
    }

    if {$width == 1} {
        puts $outfile "$name $dir"
    } else {
        # Expand bus ports bit by bit
        for {set i 0} {$i < $width} {incr i} {
            puts $outfile "${name}[$i] $dir"
        }
    }
}

close $outfile

# Create output directory if it doesn't exist
file mkdir outputs

# Open the output file
set outfile [open outputs/io_ports.txt w]

# Get all top-level ports using a wildcard pattern.
# In a synthesized netlist of a single top module, all ports are top-level.
# We use '*' to match all port names.
set ports [get_ports -filter "is_top_level==1" *]

foreach port $ports {
    # Get direction
    set dir [get_property DIRECTION $port]

    # Get port name
    set name [get_property NAME $port]

    # Get width
    set width [get_property WIDTH $port]

    # Handle cases where width might be empty or 1
    if {$width eq ""} {
        set width 1
    }

    if {$width == 1} {
        puts $outfile "$name $dir"
    } else {
        # Expand bus ports bit by bit
        for {set i 0} {$i < $width} {incr i} {
            puts $outfile "${name}[$i] $dir"
        }
    }
}

close $outfile

# Ensure the output directory exists
file mkdir outputs

# Get the top cell name
set top_cell [current_design]

# Get all instances in the design
set all_instances [get_instances -hierarchical]

# Associative array to hold counts
array set cell_counts {}

# List of patterns to exclude (physical-only cells)
# Based on the prompt: TAPCELL, FILLCELL, and typically ENDCAP cells
set exclude_patterns {
    TAPCELL*
    FILLCELL*
    *ENDCAP*
}

# Iterate through all instances and count them
foreach inst $all_instances {
    set cell_name [get_property [get_cells $inst] reference]

    # Check if this cell name matches any exclusion pattern
    set is_excluded 0
    foreach pattern $exclude_patterns {
        if {[string match $pattern $cell_name]} {
            set is_excluded 1
            break
        }
    }

    if {!$is_excluded} {
        if {[info exists cell_counts($cell_name)]} {
            incr cell_counts($cell_name)
        } else {
            set cell_counts($cell_name) 1
        }
    }
}

# Open the output file
set output_file [open "outputs/cell_usage.txt" w]

set total_count 0

# Sort the cell names for deterministic output (optional but good practice)
set sorted_cell_names [lsort [array names cell_counts]]

foreach cell_name $sorted_cell_names {
    set count $cell_counts($cell_name)
    puts $output_file "$cell_name $count"
    incr total_count $count
}

puts $output_file "total $total_count"

# Close the output file
close $output_file

# Ensure the output directory exists
file mkdir outputs

# Get all instances in the design hierarchically
# In OpenSTA, get_cells returns instances when called without specific cell name filters
set all_instances [get_cells -hierarchical *]

# Associative array to hold counts
array set cell_counts {}

# List of patterns to exclude (physical-only cells)
# Based on the prompt: TAPCELL, FILLCELL, and typically ENDCAP cells
set exclude_patterns {
    TAPCELL*
    FILLCELL*
    *ENDCAP*
}

# Iterate through all instances and count them
foreach inst $all_instances {
    # Get the reference (cell type) of the instance
    set cell_name [get_property [get_cells $inst] reference]

    # Check if this cell name matches any exclusion pattern
    set is_excluded 0
    foreach pattern $exclude_patterns {
        if {[string match $pattern $cell_name]} {
            set is_excluded 1
            break
        }
    }

    if {!$is_excluded} {
        if {[info exists cell_counts($cell_name)]} {
            incr cell_counts($cell_name)
        } else {
            set cell_counts($cell_name) 1
        }
    }
}

# Open the output file
set output_file [open "outputs/cell_usage.txt" w]

set total_count 0

# Sort the cell names for deterministic output
set sorted_cell_names [lsort [array names cell_counts]]

foreach cell_name $sorted_cell_names {
    set count $cell_counts($cell_name)
    puts $output_file "$cell_name $count"
    incr total_count $count
}

puts $output_file "total $total_count"

# Close the output file
close $output_file

# Create output directory if it doesn't exist
if {![file exists outputs]} {
    file mkdir outputs
}

# List of nets to exclude (power, ground, clock)
# Common patterns in Nangate45/OpenROAD designs:
# Power: vdd, vdd_core, vddp, etc.
# Ground: vss, vss_core, gnd, etc.
# Clock: clk, core_clock, etc.
set exclude_pattern {
    -regexp
    {^vdd$|^vdd.*|^VDD$|^VDD.*}
    {^vss$|^vss.*|^VSS$|^VSS.*|^gnd$|^gnd.*|^GND$|^GND.*}
    {^clk$|^clk.*|^CLK$|^CLK.*|^core_clock$|^core_clock.*}
}

# Get all nets in the design
set all_nets [get_nets -quiet]

# Filter out power, ground, and clock nets
set signal_nets {}
foreach net $all_nets {
    set net_name [get_name $net]

    # Check if the net name matches any exclusion pattern
    set is_excluded 0
    foreach pattern $exclude_pattern {
        if {[string match $pattern $net_name]} {
            set is_excluded 1
            break
        }
    }

    # Also explicitly check for common power/ground/clock names if regex is tricky
    if {$is_excluded == 0} {
        set lower_name [string tolower $net_name]
        if {[string match "*vdd*" $lower_name] || \
            [string match "*vss*" $lower_name] || \
            [string match "*gnd*" $lower_name] || \
            [string match "*clk*" $lower_name]} {
            set is_excluded 1
        }
    }

    if {$is_excluded == 0} {
        lappend signal_nets $net
    }
}

# Calculate fanout for each signal net and store in a list of {fanout net_name}
set fanout_list {}
foreach net $signal_nets {
    set net_name [get_name $net]

    # Get the fanout pins for this net
    # get_fanout -from $net returns a list of pins/instances driven by the net
    set fanout_pins [get_fanout -from $net]
    set fanout_count [llength $fanout_pins]

    # Append to list: {fanout_count net_name}
    lappend fanout_list [list $fanout_count $net_name]
}

# Sort the list by fanout in descending order
# If fanouts are equal, order doesn't matter
set sorted_fanout_list [lsort -decreasing -index 0 $fanout_list]

# Take the top 5
set top5 [lrange $sorted_fanout_list 0 4]

# Write the output file
set output_file "outputs/high_fanout_nets.txt"
set stream [open $output_file "w"]

foreach item $top5 {
    set fanout [lindex $item 0]
    set net_name [lindex $item 1]
    puts $stream "$net_name $fanout"
}

close $stream

mkdir -p outputs

# Get all instances
set all_insts [get_cells -hierarchical *]

# Dictionary to store initial positions: key = instance_name, value = {x y}
set initial_positions {}
set std_cell_insts {}

foreach inst $all_insts {
    # Get the cell name associated with this instance
    set cell_name [get_property cell $inst]

    # Identify standard cells by excluding known non-standard cell types
    # Exclude Fillers, Taps, and likely IOs/Macros
    if { [string match -nocase "FILLCELL*" $cell_name] || \
         [string match -nocase "TAPCELL*" $cell_name] || \
         [string match -nocase "IO*" $cell_name] || \
         [string match -nocase "MACRO*" $cell_name] || \
         [string match -nocase "BUFR*" $cell_name] || \
         [string match -nocase "BUFH*" $cell_name] } {
        continue
    }

    # Get initial location
    set loc [get_property inst_loc $inst]
    if { [llength $loc] == 2 } {
        set initial_positions($inst) $loc
        lappend std_cell_insts $inst
    }
}

# Run detailed placement with max displacement of 10 um
detailed_placement -max_displacement 10 10

# Calculate displacements
set displacements {}

foreach inst $std_cell_insts {
    if { [info exists initial_positions($inst)] } {
        set new_loc [get_property inst_loc $inst]
        if { [llength $new_loc] == 2 } {
            set old_x [lindex $initial_positions($inst) 0]
            set old_y [lindex $initial_positions($inst) 1]
            set new_x [lindex $new_loc 0]
            set new_y [lindex $new_loc 1]

            set dx [expr {abs($new_x - $old_x)}]
            set dy [expr {abs($new_y - $old_y)}]
            set disp [expr {$dx + $dy}]

            lappend displacements "$inst $disp"
        }
    }
}

# Sort displacements by value (descending)
# The format is "instance_name displacement"
# We need to sort numerically by the second field
set sorted_displacements [lsort -real -index 1 -decreasing $displacements]

# Take top 5
set top5 [lrange $sorted_displacements 0 4]

# Write to output file
set outfile [open "outputs/top_displaced.txt" w]
foreach item $top5 {
    set inst_name [lindex $item 0]
    set disp_val [lindex $item 1]
    # Format displacement with 3 decimals
    puts -nonewline $outfile "$inst_name [format %.3f $disp_val]\n"
}
close $outfile

# Run global routing
global_route

# Report global routing wirelength to a file
report_wire_length -global_route -file outputs/grt_report.txt

# Read the report file
set report [open outputs/grt_report.txt r]
set content [read $report]
close $report

# Parse the total wirelength
# Try to find "Total wirelength: XXXX um"
if {[regexp {Total wirelength:\s+(\d+\.?\d*)\s+um} $content match total_wl]} {
    set output_file [open outputs/grt_wirelength.txt w]
    puts -nonewline $output_file $total_wl
    close $output_file
} else {
    # If not found, try to parse as CSV and sum the wirelengths
    # Assume the file is CSV with a header and data rows
    set lines [split $content "\n"]
    set sum 0
    set wirelength_col -1

    # Find the header line and the wirelength column
    foreach line $lines {
        if {$line != ""} {
            # Check if it's a header line
            if {[string match "*wirelength*" [string tolower $line]] || [string match "*wl*" [string tolower $line]]} {
                set fields [split $line ","]
                for {set i 0} {$i < [llength $fields]} {incr i} {
                    set field [string trim [string tolower [lindex $fields $i]]]
                    if {$field == "wirelength" || $field == "wl"} {
                        set wirelength_col $i
                        break
                    }
                }
                if {$wirelength_col >= 0} {
                    break
                }
            }
        }
    }

    # If wirelength column is found, sum the values
    if {$wirelength_col >= 0} {
        foreach line $lines {
            if {$line != ""} {
                set fields [split $line ","]
                if {[llength $fields] > $wirelength_col} {
                    set wl [string trim [lindex $fields $wirelength_col]]
                    if {[string is double -strict $wl]} {
                        set sum [expr $sum + $wl]
                    }
                }
            }
        }
        set output_file [open outputs/grt_wirelength.txt w]
        puts -nonewline $output_file $sum
        close $output_file
    } else {
        # Fallback: try to parse the file as text and look for any number that might be the total
        # This is a last resort
        puts "Warning: Could not parse wirelength from report."
    }
}

# 1. Analyze Flip-Flop Types
set flop_instances [all_registers -cells -edge_triggered]
set total_flops [llength $flop_instances]

# Use a dict to count cell types
set flop_types_dict [dict create]

foreach inst $flop_instances {
    set cell_type [get_property [get_cells $inst] type]
    if {[dict exists $flop_types_dict $cell_type]} {
        dict set flop_types_dict $cell_type [expr {[dict get $flop_types_dict $cell_type] + 1}]
    } else {
        dict set flop_types_dict $cell_type 1
    }
}

# Write outputs/flop_types.txt
set f1 [open "outputs/flop_types.txt" w]
foreach cell_type [lsort [dict keys $flop_types_dict]] {
    puts $f1 "$cell_type [dict get $flop_types_dict $cell_type]"
}
puts $f1 "total $total_flops"
close $f1

# 2. Analyze Flip-Flop Clock Drivers
set clock_pins [all_registers -clock_pins -edge_triggered]
set driver_counts [dict create]

foreach cp $clock_pins {
    # Get the net connected to this clock pin
    set nets [get_nets -of_objects $cp]
    if {[llength $nets] == 0} {
        continue
    }
    set net [lindex $nets 0]

    # Get all pins connected to this net
    set pins [get_pins -of_objects $net]

    # Find the driver(s): pins that are outputs
    foreach pin $pins {
        set direction [get_property $pin direction]
        if {$direction eq "output"} {
            # Get the instance name of this pin
            set cell [get_property $pin cell]
            # If cell is empty, it might be a port? Standard cells should have cells.
            if {$cell ne ""} {
                # Get the instance name. The pin belongs to a cell instance.
                # In OpenSTA, get_property $pin cell returns the cell definition name?
                # No, get_property $pin cell returns the cell instance name if the pin is part of an instance.
                # Let's verify. Actually, get_property $pin cell returns the cell *definition* name usually?
                # No, for a pin object, `cell` property is the cell instance name.
                # Wait, let's look at OpenSTA docs.
                # get_pins returns pin objects.
                # get_property <pin> cell -> returns the cell instance name.

                set inst_name [get_property $pin cell]

                if {[dict exists $driver_counts $inst_name]} {
                    dict set driver_counts $inst_name [expr {[dict get $driver_counts $inst_name] + 1}]
                } else {
                    dict set driver_counts $inst_name 1
                }
            }
        }
    }
}

# Write outputs/flop_clock_drivers.txt
set f2 [open "outputs/flop_clock_drivers.txt" w]
foreach inst_name [lsort [dict keys $driver_counts]] {
    puts $f2 "$inst_name [dict get $driver_counts $inst_name]"
}
close $f2

file mkdir outputs

set clock_nets {}

# 1. Get the net driven by the clock input port clk
set clk_port [get_ports clk]
if {[llength $clk_port] > 0} {
    set clk_net [get_nets -of_objects $clk_port]
    lappend clock_nets $clk_net
}

# 2. Get nets driven by clock buffers (CLKBUF_*)
# The platform specifies CLKBUF_X1 ... CLKBUF_X3 as clock buffers.
set clk_bufs [get_cells -hierarchical -filter "type =~ CLKBUF_*"]
foreach buf $clk_bufs {
    set z_pins [get_pins -of_objects $buf Z]
    foreach z_pin $z_pins {
        set nets [get_nets -of_objects $z_pin]
        foreach net $nets {
            if {$net ni $clock_nets} {
                lappend clock_nets $net
            }
        }
    }
}

