# Parse the value from the report output. The format is typically "worst slack: <value>"
set worst_setup_slack_val 0
if {[regexp {worst slack:\s*(-?[0-9]+\.[0-9]+)} $worst_setup_slack_report match worst_setup_slack_val]} {
    # Extracted successfully
} else {
    # Fallback: try to extract just the number if format varies
    if {[regexp {(-?[0-9]+\.[0-9]+)} $worst_setup_slack_report match worst_setup_slack_val]} {
        # Success
    }
}

# Get Total Negative Setup Slack (TNS)
# report_tns reports the total negative slack for setup
set tns_report [report_tns -digits 4]
set tns_setup_val 0
if {[regexp {tns:\s*(-?[0-9]+\.[0-9]+)} $tns_report match tns_setup_val]} {
    # Extracted successfully
} else {
    if {[regexp {(-?[0-9]+\.[0-9]+)} $tns_report match tns_setup_val]} {
        # Success
    }
}

# Get Worst Hold Slack (min slack)
# report_worst_slack -min reports the worst hold slack
set worst_hold_slack_report [report_worst_slack -min -digits 4]
set worst_hold_slack_val 0
if {[regexp {worst slack:\s*(-?[0-9]+\.[0-9]+)} $worst_hold_slack_report match worst_hold_slack_val]} {
    # Extracted successfully
} else {
    if {[regexp {(-?[0-9]+\.[0-9]+)} $worst_hold_slack_report match worst_hold_slack_val]} {
        # Success
    }
}

# Count Setup Violating Endpoints
# Use report_checks to list all setup endpoints and their slacks
# We count endpoints with negative setup slack
set checks_output [report_checks -path_delay max -format summary -digits 10]
set violating_count 0
foreach line [split $checks_output "\n"] {
    # Skip empty lines
    if {[string match "" $line]} continue

    # Parse the line to get the slack value
    # The format is typically: <endpoint_name> <slack>
    # We extract the last field as the slack
    set parts [regexp -all -inline {\S+} $line]
    if {[llength $parts] < 2} continue

    set slack_str [lindex $parts end]

    # Check if the slack is negative
    if {[string match -* $slack_str]} {
        # Ensure it is a valid number
        if {[string is double -strict $slack_str]} {
            incr violating_count
        }
    }
}

