# 1. Identify all CTS buffers. Based on the prompt, they are BUF_X4.
# We use a wildcard pattern '*' with -filter to select all cells, then filter by CELL_TYPE.
# Alternatively, we can use -regexp with a pattern if we knew the naming, but CELL_TYPE filter is safer.
# Note: get_cells requires a pattern. We use '*' to match all.
set all_cells [get_cells *]
set cts_buffers [list]
foreach cell $all_cells {
    set cell_type [get_property $cell CELL_TYPE]
    if {$cell_type == "BUF_X4"} {
        lappend cts_buffers $cell
    }
}

if {[llength $cts_buffers] == 0} {
    puts "Error: No BUF_X4 cells found."
    exit 1
}

# 2. Build a map of buffer input net -> list of buffer instances driven by that net
# Also identify the root buffer (driven by clk port)

set clk_port [get_ports clk]
if {[llength $clk_port] == 0} {
    puts "Error: Clock port clk not found."
    exit 1
}

set clk_net [get_nets -of $clk_port]

# Map: input_net_name -> list of buffer instance names
set net_to_drivers [dict create]
set root_buffer ""

foreach buf $cts_buffers {
    set buf_name [get_name $buf]
    set input_pin [get_pin -of $buf A]
    set input_net [get_net -of $input_pin]
    set input_net_name [get_name $input_net]

    if {![dict exists $net_to_drivers $input_net_name]} {
        dict set net_to_drivers $input_net_name [list]
    }
    lappend [dict get $net_to_drivers $input_net_name] $buf_name

    # Check if this buffer is driven by the clock port net
    if {$input_net_name == [get_name $clk_net]} {
        set root_buffer $buf_name
    }
}

if {$root_buffer == ""} {
    puts "Error: Could not find root buffer driven by clk."
    exit 1
}

# 3. Assign levels using BFS
# Map: buffer_name -> level
set buffer_levels [dict create]
dict set buffer_levels $root_buffer 1

set current_level 1
set current_level_buffers [list $root_buffer]

while {[llength $current_level_buffers] > 0} {
    set next_level_buffers [list]
    set next_level [expr {$current_level + 1}]

    foreach buf_name $current_level_buffers {
        # Find the output net(s) of this buffer
        set buf [get_cells $buf_name]
        set output_pins [get_pins -of $buf -filter "DIRECTION == OUT"]

        foreach out_pin $output_pins {
            set out_net [get_net -of $out_pin]
            set out_net_name [get_name $out_net]

            # Find all instances driven by this output net
            # We need input pins connected to this net
            set driven_pins [get_pins -filter "NET == $out_net_name && DIRECTION == IN"]

            foreach driven_pin $driven_pins {
                set driven_inst [get_cell -of $driven_pin]
                set driven_inst_name [get_name $driven_inst]

                # Check if this driven instance is a CTS buffer
                # We need to check if it's a BUF_X4
                set driven_cell_type [get_property $driven_inst CELL_TYPE]

                if {$driven_cell_type == "BUF_X4"} {
                    # If not already assigned a level, assign it
                    if {![dict exists $buffer_levels $driven_inst_name]} {
                        dict set buffer_levels $driven_inst_name $next_level
                        lappend next_level_buffers $driven_inst_name
                    }
                }
            }
        }
    }

    set current_level_buffers $next_level_buffers
    incr current_level
}

# 4. Count register sinks for each buffer
# Register sinks are clock pins of flip-flops connected directly to the buffer's output net.

set output_lines [list]

foreach buf_name [dict keys $buffer_levels] {
    set level [dict get $buffer_levels $buf_name]
    set buf [get_cells $buf_name]

    set sink_count 0

    # Get output pins
    set output_pins [get_pins -of $buf -filter "DIRECTION == OUT"]

    foreach out_pin $output_pins {
        set out_net [get_net -of $out_pin]
        set out_net_name [get_name $out_net]

        # Get all pins connected to this net
        set net_pins [get_pins -filter "NET == $out_net_name"]

        foreach pin $net_pins {
            set pin_inst [get_cell -of $pin]
            set pin_name [get_name $pin]
            set pin_direction [get_property $pin DIRECTION]

            # Check if this pin is a clock pin of a register
            # We check if the pin direction is IN (which it should be for a load)
            if {$pin_direction == "IN"} {
                # Check if the cell is a register
                # We can check if the cell has a clock port.
                set cell_ports [get_ports -of $pin_inst]
                set is_register 0
                foreach port $cell_ports {
                    set port_name [get_name $port]
                    # Common clock port names
                    if {[string match -nocase "*CLK*" $port_name] || [string match -nocase "*CK*" $port_name]} {
                        set is_register 1
                        break
                    }
                }

                if {$is_register} {
                    incr sink_count
                }
            }
        }
    }

    lappend output_lines "$buf_name BUF_X4 $level $sink_count"
}

# 5. Write to file
set output_file "outputs/ct06_clock_tree.txt"
set fid [open $output_file w]
foreach line $output_lines {
    puts $fid $line
}
close $fid

