# Function to calculate HPWL
proc calc_hpwl {} {
    set total_hpwl 0.0
    set nets [get_nets -hier]

    foreach net $nets {
        set net_name [get_property $net NAME]

        # Skip power and ground nets
        # Common power/ground net names
        if {[string match -nocase "*VDD*" $net_name] || \
            [string match -nocase "*VSS*" $net_name] || \
            [string match -nocase "*GND*" $net_name] || \
            [string match -nocase "*power*" $net_name] || \
            [string match -nocase "*ground*" $net_name]} {
            continue
        }

        # Get pins of the net
        set pins [get_pins -of_objects $net]

        # Check if net has at least two pins
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 1e9
        set max_x -1e9
        set min_y 1e9
        set max_y -1e9

        set found_pin 0

        foreach pin $pins {
            # Get center coordinates
            # Try to get X and Y properties
            set x [get_property $pin X]
            set y [get_property $pin Y]

            # If X/Y properties are not available, try to get from bbox
            if {$x eq "" || $y eq ""} {
                # Try to get bounding box of the pin shape
                # This is more complex and might not be directly available via simple get_property
                # Let's assume X and Y are available for placed pins
                continue
            }

            set found_pin 1

            if {$x < $min_x} { set min_x $x }
            if {$x > $max_x} { set max_x $x }
            if {$y < $min_y} { set min_y $y }
            if {$y > $max_y} { set max_y $y }
        }

        if {$found_pin} {
            set hpwl_net [expr {($max_x - $min_x) + ($max_y - $min_y)}]
            set total_hpwl [expr {$total_hpwl + $hpwl_net}]
        }
    }

    return $total_hpwl
}

# Ensure output directory exists
if {![file exists outputs]} {
    file mkdir outputs
}

# Calculate HPWL before optimization
set hpwl_before [calc_hpwl]

# Run optimize_mirroring
optimize_mirroring

# Calculate HPWL after optimization
set hpwl_after [calc_hpwl]

# Write results
set fp [open "outputs/hpwl.txt" w]
puts $fp "hpwl_before_um: [format "%.2f" $hpwl_before]"
puts $fp "hpwl_after_um: [format "%.2f" $hpwl_after]"
close $fp

# Run global routing
global_route

# Report global routing wirelength to a temporary file
# Note: -net * is required to report on all nets
report_wire_length -net * -global_route -file outputs/grt_report.txt

# Read the report to extract the total wirelength
set fp [open outputs/grt_report.txt r]
set report [read $fp]
close $fp

# Extract the total wirelength value
# The report typically contains a line like: "Total wirelength: 12345 um"
if {[regexp {Total wirelength:\s*([0-9]+\.?[0-9]*)\s*um} $report -> wl]} {
    set fp_out [open outputs/grt_wirelength.txt w]
    puts -nonewline $fp_out $wl
    close $fp_out
} else {
    # Fallback: try to find the number without the 'um' suffix just in case
    if {[regexp {Total wirelength:\s*([0-9]+\.?[0-9]*)} $report -> wl]} {
        set fp_out [open outputs/grt_wirelength.txt w]
        puts -nonewline $fp_out $wl
        close $fp_out
    } else {
        error "Failed to parse total wirelength from report."
    }
}

# Create the output directory if it doesn't exist
if {[file exists outputs] == 0} {
    file mkdir outputs
}

# Get the clock port
set clk_port [get_ports clk]
if {$clk_port == ""} {
    puts "Warning: Clock port 'clk' not found."
    set clk_net ""
} else {
    # Get the net connected to the clock port
    set clk_net [get_nets -of_objects $clk_port]
    if {$clk_net == ""} {
