    set direction [get_property DIRECTION $port]

    # Get the port width (number of bits)
    set width [get_property WIDTH $port]

    # If width is 1, just write the port name and direction
    if {$width == 1} {
        puts $outfile "$port_name $direction"
    } else {
        # If it's a bus, expand it bit by bit
        for {set i 0} {$i < $width} {incr i} {
            puts $outfile "${port_name}[$i] $direction"
        }
    }
}

# Close the output file
close $outfile

