# Initialize a dictionary to store cell counts
set cell_counts [dict create]
set total_count 0

# Get all instances in the design
set instances [get_cells -hierarchical *]

foreach inst $instances {
    # Get the cell name for this instance
    set cell_name [get_property $inst cell_name]

    # Skip empty cell names (e.g., if it's a black box or undefined, though unlikely in a placed design)
    if {$cell_name eq ""} {
        continue
    }

    # Check if the cell is a physical-only cell (tap, endcap, or filler)
    # Based on the platform description:
    # Tap/endcap: TAPCELL_X1 (and potentially others starting with TAP or ENDCAP)
    # Fillers: FILLCELL_X1 ... FILLCELL_X32 (pattern FILLCELL*)
    # We will exclude cells starting with TAP, ENDCAP, or FILL

    set is_physical_only 0
    if {[string match -nocase "TAP*" $cell_name]} {
        set is_physical_only 1
    } elseif {[string match -nocase "ENDCAP*" $cell_name]} {
        set is_physical_only 1
    } elseif {[string match -nocase "FILL*" $cell_name]} {
        set is_physical_only 1
    }

    # If it's not a physical-only cell, count it
    if {!$is_physical_only} {
        if {[dict exists $cell_counts $cell_name]} {
            set current_count [dict get $cell_counts $cell_name]
            dict set cell_counts $cell_name [expr {$current_count + 1}]
        } else {
            dict set cell_counts $cell_name 1
        }
        incr total_count
    }
}

