foreach pin $input_pins {
    # Get the net connected to this pin
    set net [get_property $pin net]

    # If the pin is not connected to a net (e.g., top-level input port), skip
    if {$net eq ""} {
        continue
    }

    # Get net name
    set net_name [get_name $net]

    # Skip power/ground nets
    if {[string match -nocase "*VDD*" $net_name] || \
        [string match -nocase "*VSS*" $net_name] || \
        [string match -nocase "*GND*" $net_name] || \
        [string match -nocase "*VPWR*" $net_name] || \
        [string match -nocase "*VGND*" $net_name]} {
        continue
    }

    # Skip clock nets
    if {$net_name eq "clk" || $net_name eq "core_clock"} {
        continue
    }

    # Increment count
    if {[info exists fanout_counts($net_name)]} {
        incr fanout_counts($net_name)
    } else {
        set fanout_counts($net_name) 1
    }
}

# Also count top-level output ports connected to nets
# The task says: "input pins of cell instances plus top-level output ports connected to the net"
# get_pins -filter {direction == in} only gets cell inputs.
# We need to add top-level output ports.
# Top-level output ports are ports of the top cell.
set top_cell [current_design]
set top_ports [get_ports -of_objects $top_cell]

foreach port $top_ports {
    # Check if it's an output port
    if {[get_property $port direction] eq "out"} {
        set net [get_property $port net]
        if {$net ne ""} {
            set net_name [get_name $net]

            # Skip special nets
            if {[string match -nocase "*VDD*" $net_name] || \
                [string match -nocase "*VSS*" $net_name] || \
                [string match -nocase "*GND*" $net_name] || \
                [string match -nocase "*VPWR*" $net_name] || \
                [string match -nocase "*VGND*" $net_name]} {
                continue
            }
            if {$net_name eq "clk" || $net_name eq "core_clock"} {
                continue
            }

            if {[info exists fanout_counts($net_name)]} {
                incr fanout_counts($net_name)
            } else {
                set fanout_counts($net_name) 1
            }
        }
    }
}

