# Helper to check if a net is a power/ground net
proc is_power_ground_net { net_name } {
    if { [string match -nocase "*VDD*" $net_name] || \
         [string match -nocase "*VSS*" $net_name] || \
         [string match -nocase "*GND*" $net_name] || \
         [string match -nocase "*vdd*" $net_name] || \
         [string match -nocase "*vss*" $net_name] || \
         [string match -nocase "*gnd*" $net_name] } {
        return 1
    }
    return 0
}

# Function to calculate total HPWL excluding power/ground nets
proc get_total_hpwl {} {
    set total_hpwl 0.0

    # Get all nets using wildcard pattern
    set nets [get_nets *]

    foreach net_name $nets {
        # Skip power and ground nets
        if { [is_power_ground_net $net_name] } {
            continue
        }

        # Get pins of the net
        set pins [get_pins -of_objects [get_nets $net_name]]

        # If fewer than 2 pins, HPWL is 0
        if { [llength $pins] < 2 } {
            continue
        }

        set min_x 1e9
        set max_x -1e9
        set min_y 1e9
        set max_y -1e9

        foreach pin $pins {
            set pin_name [get_full_name $pin]
            set pin_type [sta::object_type $pin]

            set x 0
            set y 0

            if { $pin_type == "Port" } {
                # It's an IO port
                lassign [sta::port_location $pin] x y
            } elseif { $pin_type == "Pin" } {
                # It's an instance pin
                lassign [sta::pin_location $pin] x y
            } else {
                # Unknown type, skip or handle appropriately
                continue
            }

            if { $x < $min_x } { set min_x $x }
            if { $x > $max_x } { set max_x $x }
            if { $y < $min_y } { set min_y $y }
            if { $y > $max_y } { set max_y $y }
        }

        # Calculate HPWL for this net
        set width [expr {$max_x - $min_x}]
        set height [expr {$max_y - $min_y}]
        set hpwl [expr {$width + $height}]

        set total_hpwl [expr {$total_hpwl + $hpwl}]
    }

    return $total_hpwl
}

# 1. Calculate HPWL before optimization
set hpwl_before [get_total_hpwl]

# 2. Run detailed placement optimization
# optimize_mirroring reduces HPWL by mirroring cells within legal placement constraints
optimize_mirroring

# 3. Calculate HPWL after optimization
set hpwl_after [get_total_hpwl]

