# 1. Capture pre-legalization positions
# Use ord::get_db_block to access the database block
set db_block [ord::get_db_block]

# Create an associative array to store initial positions: instance_name -> {x y}
set pre_pos [dict create]

# Get all instances in the design
set instances [ord::dbInsts $db_block]

foreach inst $instances {
    # Skip macros
    if {[ord::dbInstIsMacro $inst]} {
        continue
    }

    # Get cell name to filter fillers, tap cells, etc.
    set db_cell [ord::dbInstGetMaster $inst]
    set cell_name [ord::dbMasterGetName $db_cell]

    # Skip fillers, tap cells, tie cells, clock buffers (standard cells only)
    if {[string match "FILLCELL*" $cell_name]} {
        continue
    }
    if {[string match "TAPCELL*" $cell_name]} {
        continue
    }
    if {[string match "LOGIC0*" $cell_name]} {
        continue
    }
    if {[string match "LOGIC1*" $cell_name]} {
        continue
    }
    if {[string match "CLKBUF*" $cell_name]} {
        continue
    }

    # Get current location (lower-left corner) in microns
    # ord::dbInstGetX and ord::dbInstGetY return coordinates in database units (microns)
    set x [ord::dbInstGetX $inst]
    set y [ord::dbInstGetY $inst]

    set inst_name [ord::dbInstGetName $inst]
    dict set pre_pos $inst_name [list $x $y]
}

# 2. Run Detailed Placement with max displacement constraint
# The task requires: no cell may move by more than 10 um.
detailed_placement -max_displacement 10

# 3. Calculate displacements and find top 5
set displacements [dict create]

foreach inst $instances {
    if {[ord::dbInstIsMacro $inst]} {
        continue
    }

    set db_cell [ord::dbInstGetMaster $inst]
    set cell_name [ord::dbMasterGetName $db_cell]

    if {[string match "FILLCELL*" $cell_name]} {
        continue
    }
    if {[string match "TAPCELL*" $cell_name]} {
        continue
    }
    if {[string match "LOGIC0*" $cell_name]} {
        continue
    }
    if {[string match "LOGIC1*" $cell_name]} {
        continue
    }
    if {[string match "CLKBUF*" $cell_name]} {
        continue
    }

    set inst_name [ord::dbInstGetName $inst]

    # Check if we have pre-position for this instance
    if {![dict exists $pre_pos $inst_name]} {
        continue
    }

    set pre_loc [dict get $pre_pos $inst_name]
    set pre_x [lindex $pre_loc 0]
    set pre_y [lindex $pre_loc 1]

    # Get post-legalization location
    set post_x [ord::dbInstGetX $inst]
    set post_y [ord::dbInstGetY $inst]

    # Calculate Manhattan distance
    set dx [expr {abs($post_x - $pre_x)}]
    set dy [expr {abs($post_y - $pre_y)}]
    set disp [expr {$dx + $dy}]

    dict set displacements $inst_name $disp
}

# Sort instances by displacement descending
# Create a list of {instance_name displacement}
set sorted_list [list]
foreach {name disp} [dict get $displacements] {
    lappend sorted_list [list $name $disp]
}

# Sort the list by displacement (index 1) in descending order
set sorted_list [lsort -real -index 1 -decreasing $sorted_list]

# Take top 5
set top_5 [lrange $sorted_list 0 4]

# Write to output file
set fid [open "outputs/top_displaced.txt" w]
foreach item $top_5 {
    set name [lindex $item 0]
    set disp [lindex $item 1]
    # Format displacement with 3 decimals
    fprintf $fid "%s %.3f\n" $name $disp
}
