# Parse the temporary file and write to the final output file
set out_file outputs/clock_gr_wirelength.txt
set out_fh [open $out_file w]

set temp_fh [open $temp_file r]
set first_line 1
while {[gets $temp_fh line] >= 0} {
    # Skip header lines if they start with '#' or contain 'Net' and 'Wirelength'
    if {$first_line} {
        if {[string match "*Net*Wirelength*" $line] || [string match "*Net*WL*" $line] || [string match "#*" $line]} {
            set first_line 1
            continue
        }
        set first_line 0
    }

    # Skip empty lines
    if {[string trim $line] eq ""} {
        continue
    }

    # Parse the line. It might be CSV or space-separated.
    # Try splitting by comma first
    set parts [split $line ","]
    if {[llength $parts] >= 2} {
        set net_name [string trim [lindex $parts 0]]
        set wirelength [string trim [lindex $parts 1]]
    } else {
        # Try splitting by whitespace
        set parts [regexp -all -inline {\S+} $line]
        if {[llength $parts] >= 2} {
            set net_name [lindex $parts 0]
            set wirelength [lindex $parts 1]
        } else {
            continue
        }
    }

    # Validate wirelength is a number
    if {[string is double -strict $wirelength]} {
        puts $out_fh "$net_name $wirelength"
    }
}
close $temp_fh
