# Read the generated report
set report_content [open "outputs/_temp_report.log" r]
set report_text [read $report_content]
close $report_content

# Initialize lists for violating pins
set slew_violators {}
set cap_violators {}

# Parse the report text to find violating pins
# OpenROAD report_check_types typically outputs lines like:
# [Violation] max_slew ... pin u1/Z ...
# or
# [Violation] max_capacitance ... pin u1/Z ...
# We look for lines containing "max_slew" or "max_capacitance" and extract the pin name.

foreach line [split $report_text "\n"] {
    # Check for max_slew violation
    if {[string match "*max_slew*" $line] && [string match "*pin*" $line]} {
        # Extract pin name. The format is usually "pin <name>"
        if {[regexp {pin\s+([a-zA-Z0-9_/\.\[\]]+)} $line match pin_name]} {
            lappend slew_violators $pin_name
        }
    }

    # Check for max_capacitance violation
    if {[string match "*max_capacitance*" $line] && [string match "*pin*" $line]} {
        if {[regexp {pin\s+([a-zA-Z0-9_/\.\[\]]+)} $line match pin_name]} {
            lappend cap_violators $pin_name
        }
    }
}

# Remove duplicates and sort the lists
set slew_violators [lsort -unique $slew_violators]
set cap_violators [lsort -unique $cap_violators]

# Write slew violations to the output file
set fp_slew [open "outputs/max_transition_violations.rpt" w]
if {[llength $slew_violators] == 0} {
    puts $fp_slew "No max transition violations found."
} else {
    puts $fp_slew "Max Transition Violations:"
    foreach pin $slew_violators {
        puts $fp_slew $pin
    }
}
close $fp_slew

# Write capacitance violations to the output file
set fp_cap [open "outputs/max_capacitance_violations.rpt" w]
if {[llength $cap_violators] == 0} {
    puts $fp_cap "No max capacitance violations found."
} else {
    puts $fp_cap "Max Capacitance Violations:"
    foreach pin $cap_violators {
        puts $fp_cap $pin
    }
}
close $fp_cap

